-- Free plan: two agents per account. The check runs inside the insert, so two
-- creates cannot both pass a count taken before either write.
-- Keep the bound in step with AGENT_LIMIT in src/tenants/create.ts.
-- Append-only: do not edit this file.
CREATE TRIGGER IF NOT EXISTS tenants_agent_limit
BEFORE INSERT ON tenants
FOR EACH ROW
WHEN (SELECT COUNT(*) FROM tenants WHERE owner_account_id = NEW.owner_account_id) >= 2
BEGIN
  SELECT RAISE(ABORT, 'agent_limit');
END;
